def ortalama(vals):
    return sum(vals) / len(vals)

m1 = [10, 20, 30]     # 1. harita gorevinin degerleri
m2 = [100]            # 2. harita gorevinin degerleri

print("combiner yok :", ortalama(m1 + m2))

ara = [ortalama(m1), ortalama(m2)]     # combiner = reducer
print("combiner var :", ortalama(ara))

def kismi(vals):
    return (sum(vals), len(vals))
p1, p2 = kismi(m1), kismi(m2)
toplam = (p1[0] + p2[0], p1[1] + p2[1])
print("toplam,adet  :", toplam[0] / toplam[1])
